const input = $json.body || $json;

const required = ['avatar', 'scene', 'assetType'];
const missing = required.filter(k => !input[k]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

return [{
  json: {
    avatar: input.avatar,
    scene: input.scene,
    assetType: input.assetType,
    baseUrl: input.baseUrl || 'http://192.168.0.194:9000',
    limit: input.limit || 50,
    includeCanonical: input.includeCanonical !== false
  }
}];

const params = $('Normalize Request').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.asset_id);

const candidates = rows.map(r => ({
  assetId: r.asset_id,
  avatar: r.avatar,
  scene: r.scene,
  assetType: r.asset_type,
  url: `${params.baseUrl}/${r.bucket}/${r.object_path}`,
  bucket: r.bucket,
  objectPath: r.object_path,
  mimeType: r.mime_type,
  status: r.status,
  isCanonical: r.is_canonical,
  sha256: r.sha256,
  canonicalGroup: r.canonical_group,
  reviewNotes: r.review_notes,
  createdAt: r.created_at
}));

return [{
  json: {
    status: 'ok',
    count: candidates.length,
    avatar: params.avatar,
    scene: params.scene,
    assetType: params.assetType,
    candidates
  }
}];
